"""Build Meridian Contract Liability workbook.

This script follows the detailed step‑by‑step specification provided in the task prompt.
It loads the provided source files, processes the contract records, applies manual
overrides/insertions, computes month‑roll balances, and writes the results into a
new workbook ``Meridian_Contract_Liability_12-25.xlsx`` based on the supplied
``liability_template.xlsx``.
"""

import json
import csv
import sys
from pathlib import Path
from collections import defaultdict
from copy import deepcopy

import openpyxl
from openpyxl.utils import get_column_letter

ROOT = Path("/root")

# ---------------------------------------------------------------------------
# Helper utilities
# ---------------------------------------------------------------------------
def load_json(path: Path):
    with path.open() as f:
        return json.load(f)

def load_csv_mapping(path: Path):
    """Return a dict mapping source_bucket -> dict with sheet_name, gl_key, account_number."""
    mapping = {}
    with path.open(newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            mapping[row["source_bucket"]] = {
                "sheet_name": row["sheet_name"],
                "gl_key": row["gl_key"],
                "account_number": row["account_number"],
            }
    return mapping

def load_manual_bridge(path: Path):
    """Return a list of dicts representing each bridge row."""
    bridges = []
    with path.open(newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            bridges.append(row)
    return bridges

def bool_true(val):
    if isinstance(val, bool):
        return val
    if isinstance(val, str):
        return val.lower() == "true"
    return bool(val)

def safe_int(val):
    if val in ("", None):
        return None
    try:
        return int(val)

